import{_ as a,a as s}from"./chunks/jobbench_leaderboard_ja.D2AZBuFs.js";import{c as n,Q as t,j as i,m as o}from"./chunks/framework.t4rEqR7d.js";const b=JSON.parse('{"title":"ベンチマーク","description":"","frontmatter":{},"headers":[],"relativePath":"ja/benchmarks.md","filePath":"ja/benchmarks.md"}'),p={name:"ja/benchmarks.md"};function r(l,e,h,d,c,g){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="ベンチマーク" tabindex="-1">ベンチマーク <a class="header-anchor" href="#ベンチマーク" aria-label="Permalink to &quot;ベンチマーク&quot;">​</a></h1><p><code>deepseek-v4-flash</code> をプレイヤーとして <a href="https://job-bench.github.io/" target="_blank" rel="noreferrer">JobBench</a> を実行し、2 つの harness——公式の <strong>OpenCode</strong> と pagentv4 の <strong>inplace</strong> モード （<code>CodeRunner + InplaceBackend</code>）——を比較しました。両 harness は同一のプレイヤー モデルと同一の審査（<code>deepseek-v4-pro</code>、temperature 0）を使い、harness と split のみが異なります。</p><div class="warning custom-block"><p class="custom-block-title">審査は公式リーダーボードと異なる</p><p>公式リーダーボードの審査は <strong>Grok 4.3</strong> ですが、ここでは <strong>deepseek-v4-pro</strong> （プレイヤーと同一ベンダーのため甘め）で採点しています。本リポジトリのスコアは 参考値であり、公式ボードとは<strong>直接比較できません</strong>。該当行には <code>*</code> を付けています。</p></div><h2 id="opencode-vs-pagentv4" tabindex="-1">OpenCode vs pagentv4 <a class="header-anchor" href="#opencode-vs-pagentv4" aria-label="Permalink to &quot;OpenCode vs pagentv4&quot;">​</a></h2><p>同一プレイヤー・同一審査で harness のみ変更。両 split で pagentv4 が上回ります。</p><p><img src="'+a+'" alt="JobBench の Easy と Main split における OpenCode と pagentv4 の比較。micro スコアで pagentv4 が Easy で +4.5、Main で +1.6 リード"></p><ul><li><strong>Easy split：</strong> pagentv4 <strong>80.0</strong> vs OpenCode 75.5（micro）。</li><li><strong>Main split：</strong> pagentv4 <strong>38.2</strong> vs OpenCode 36.6（micro）。</li><li>Main では pagentv4 が ≥0.8 のタスクを 5 件（うち 1 件は満点）獲得、OpenCode は 1 件。</li></ul><p><code>micro</code> = 合計 / 満点（rubric 重み付け）。<code>macro</code> = タスクごとの正規化スコアの等重平均。</p><h2 id="main-リーダーボードでの位置" tabindex="-1">Main リーダーボードでの位置 <a class="header-anchor" href="#main-リーダーボードでの位置" aria-label="Permalink to &quot;Main リーダーボードでの位置&quot;">​</a></h2><p>公式ボードは Main split のみを集計します。本リポジトリの 2 つの harness をその ランキングに挿入した図（審査基準が異なるため参考）：</p><p><img src="'+s+`" alt="JobBench Main split リーダーボード。deepseek-v4-flash が pagentv4 で 38.2、OpenCode で 36.6、GPT-5.5 と Claude Sonnet 4.6 の間に位置"></p><ul><li><strong>pagentv4 = 38.2</strong>：GPT-5.5（38.3）と Claude Sonnet 4.6（36.6）の間。</li><li><strong>OpenCode = 36.6</strong>：Claude Sonnet 4.6 と同点。</li></ul><h2 id="再現" tabindex="-1">再現 <a class="header-anchor" href="#再現" aria-label="Permalink to &quot;再現&quot;">​</a></h2><p>図は <code>examples/eval/jobbench_scores.json</code> から生成し、<code>examples/eval/</code> と <code>docs/public/benchmarks/</code>（VitePress サイト資産）の両方に書き出します：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/eval/aggregate_scores.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/eval/jobbench_scores.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --with</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> matplotlib</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/eval/plot_jobbench_leaderboard.py</span></span></code></pre></div><p>方法論の詳細、タスクごとの内訳、実行コマンドは <a href="https://github.com/SyncLionPaw/pagent/blob/main/examples/eval/REPORT_jobbench_deepseek-v4-flash.md" target="_blank" rel="noreferrer"><code>examples/eval/REPORT_jobbench_deepseek-v4-flash.md</code></a> を参照してください。</p>`,16)])])}const v=n(p,[["render",r]]);export{b as __pageData,v as default};
